import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/moran_local_no2crime_no2_Q2_2023.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Get the boroughs and their neighbors
boroughs = df['borough'].unique()
neighbors = adjacency['neighbor'].unique()

# Create a dictionary to store the NO2 values for each borough
no2_values = {}
for borough in boroughs:
    no2_values[borough] = df.loc[df['borough'] == borough, 'value'].iloc[0]

# Create a dictionary to store the NO2 values for each neighbor
neighbor_no2_values = {}
for neighbor in neighbors:
    neighbor_no2_values[neighbor] = df.loc[df['borough'] == neighbor, 'value'].iloc[0]

# Function to calculate the average NO2 value for a borough and its neighbors
def calculate_average_no2(borough):
    no2_values = [no2_values[borough]]
    for neighbor in adjacency.loc[adjacency['borough'] == borough, 'neighbor']:
        no2_values.append(neighbor_no2_values[neighbor])
    return np.mean(no2_values)

# Function to calculate the standard deviation of the NO2 values for a borough and its neighbors
def calculate_std_no2(borough):
    no2_values = [no2_values[borough]]
    for neighbor in adjacency.loc[adjacency['borough'] == borough, 'neighbor']:
        no2_values.append(neighbor_no2_values[neighbor])
    return np.std(no2_values)

# Function to calculate the Moran's I statistic
def moran_i(borough):
    no2_values = [no2_values[borough]]
    for neighbor in adjacency.loc[adjacency['borough'] == borough, 'neighbor']:
        no2_values.append(neighbor_no2_values[neighbor])
    mean_no2 = np.mean(no2_values)
    variance_no2 = np.var(no2_values)
    return (np.sum([(no2_values[i] - mean_no2) ** 2 for i in range(len(no2_values))]) / (len(no2_values) - 1)) / variance_no2

# Function to perform a permutation test for Moran's I
def permutation_test(borough, num_permutations=500):
    moran_i_values = []
    for _ in range(num_permutations):
        np.random.shuffle(no2_values[borough])
        for neighbor in adjacency.loc[adjacency['borough'] == borough, 'neighbor']:
            np.random.shuffle(neighbor_no2_values[neighbor])
        moran_i_values.append(moran_i(borough))
    return np.mean(moran_i_values)

# Identify hot spots and cold spots
hot_spots = []
cold_spots = []
for borough in boroughs:
    average_no2 = calculate_average_no2(borough)
    std_no2 = calculate_std_no2(borough)
    moran_i_value = moran_i(borough)
    p_value = permutation_test(borough)
    print(f"Borough: {borough}, Average NO2: {average_no2}, Standard Deviation NO2: {std_no2}, Moran's I: {moran_i_value}, p-value: {p_value}")
    if average_no2 > 20 and moran_i_value > 0.5 and p_value < 0.05:
        hot_spots.append((borough, 'HH', moran_i_value))
    elif average_no2 < 10 and moran_i_value < -0.5 and p_value < 0.05:
        cold_spots.append((borough, 'LL', moran_i_value))

# Print the final answer
print(f"FINAL ANSWER: {', '.join([f'{borough} ({spot[1]}, statistical method={spot[2]})' for borough, spot in hot_spots + cold_spots])}")
